{
  "query": "query GetProduct($productId: ID!) { product(productId: $productId) { productId name description category brand price currency images tags status weight dimensions color material additionalSpecs { key value } } }",
  "variables": {
    "productId": "{{PRODUCT_ID}}"
  }
}

{
  "query": "query GetProducts($page: Int!, $size: Int!, $sortBy: String!) { products(page: $page, size: $size, sortBy: $sortBy) { content { productId name price status } page size totalElements totalPages last } }",
  "variables": {
    "page": 0,
    "size": 20,
    "sortBy": "name"
  }
}

{
  "query": "query ProductsByCategory($category: String!, $page: Int!, $size: Int!) { productsByCategory(category: $category, page: $page, size: $size) { content { productId name price } totalElements totalPages } }",
  "variables": {
    "category": "Electronics",
    "page": 0,
    "size": 20
  }
}

{
  "query": "query ProductsByStatus($status: ProductStatus!, $page: Int!, $size: Int!) { productsByStatus(status: $status, page: $page, size: $size) { content { productId name status } totalElements totalPages } }",
  "variables": {
    "status": "ACTIVE",
    "page": 0,
    "size": 20
  }
}

{
  "query": "query SearchProducts($keyword: String!, $category: String, $minPrice: BigDecimal, $maxPrice: BigDecimal, $page: Int!, $size: Int!) { searchProducts(keyword: $keyword, category: $category, minPrice: $minPrice, maxPrice: $maxPrice, page: $page, size: $size) { content { productId name price } totalElements totalPages } }",
  "variables": {
    "keyword": "laptop",
    "category": "Electronics",
    "minPrice": 500,
    "maxPrice": 2000,
    "page": 0,
    "size": 20
  }
}

{
  "query": "mutation CreateProduct($input: ProductInput!) { createProduct(input: $input) { productId name price status } }",
  "variables": {
    "input": {
      "productId": "{{PRODUCT_ID}}",
      "name": "Premium Laptop",
      "description": "High-performance laptop with 16GB RAM and 512GB SSD",
      "category": "Electronics",
      "brand": "TechBrand",
      "price": 1299.99,
      "currency": "USD",
      "images": ["https://example.com/laptop-front.jpg"],
      "tags": ["laptop", "electronics"],
      "weight": "1.8kg",
      "dimensions": "35x24x1.8cm",
      "color": "Silver",
      "material": "Aluminum",
      "additionalSpecs": [
        { "key": "ram", "value": "16GB" },
        { "key": "storage", "value": "512GB SSD" }
      ]
    }
  }
}

{
  "query": "mutation UpdateProduct($productId: ID!, $input: ProductInput!) { updateProduct(productId: $productId, input: $input) { productId name price status } }",
  "variables": {
    "productId": "{{PRODUCT_ID}}",
    "input": {
      "productId": "{{PRODUCT_ID}}",
      "name": "Premium Laptop - Updated",
      "description": "High-performance laptop with 32GB RAM and 1TB SSD",
      "category": "Electronics",
      "brand": "TechBrand",
      "price": 1499.99,
      "currency": "USD",
      "images": ["https://example.com/laptop-front-v2.jpg"],
      "tags": ["laptop", "electronics", "premium"],
      "weight": "1.7kg",
      "dimensions": "35x24x1.7cm",
      "color": "Space Gray",
      "material": "Aluminum",
      "additionalSpecs": [
        { "key": "ram", "value": "32GB" },
        { "key": "storage", "value": "1TB SSD" }
      ]
    }
  }
}
